STAGES = {"approach":[["Well, {name} is settling in","Okay, {name} takes a moment","There goes {name}, nice and easy","All right, {name} steps up","Look at that, {name} is getting comfortable"],["on the approach. Let's see what happens.","with a little room to breathe, man.","and the lane is just waiting there.","no need to rush a thing.","looking for a smooth release, you know."]],"path":[["And there it goes","That ball is on its way","Okay, we've got motion","Well, the ball is rolling","There goes the delivery"],["down the boards, nice and steady.","and we'll see where it ends up, man.","taking its own sweet time.","with a little journey ahead of it.","heading toward the rack, easy does it."]],"breakpoint":[["Now that's the turn","There's the hook coming in","Okay, watch that change of direction","The ball is finding its angle","Well, here comes the bend"],["and the pins are waiting, man.","right around the breakpoint.","a little late drama on the lane.","and we'll see if it holds.","with a bit of character to it."]],"impact":[["Here we go, into the deck","Well, that's contact","The ball meets the pins","Okay, things are happening down there","That's the collision"],["let's see what stays standing.","give it a second to settle, man.","and we're waiting on the count.","no calling it too early.","the rack gets the final word."]]}
EVENTS = {"strike":[["Well, {name} clears the whole rack","That's ten for {name}","Okay, {name} found the pocket","Every pin went down for {name}","A clean strike from {name}"],["and that's a beautiful thing, man.","like it was always meant to happen.","very smooth, very mellow.","the pins really tied that shot together.","nothing left to argue about."]],"spare":[["{name} picks up the spare","A tidy cleanup by {name}","Well, {name} gets the rest","That's a spare for {name}","{name} takes care of the leftovers"],["nice and easy, man.","that's how you keep it rolling.","no loose ends on that one.","a little patience pays off.","very respectable indeed."]],"split":[["Oh, {name} has a split: {leave}","That rack opens up on {name}: {leave}","Well, that's a tricky {leave} for {name}","{name} is staring at {leave}","A split for {name}, {leave}"],["that's a complicated arrangement, man.","could take a little finesse.","not exactly a relaxing sight.","the pins have their own ideas.","well, that's bowling for you."]],"split_convert":[["{name} converts the {leave} split","Well, look at that, {name} gets the {leave}","The {leave} goes down for {name}","{name} pulls off the {leave} conversion","That {leave} split is gone, courtesy of {name}"],["that is something else, man.","I did not see that coming.","beautifully worked out.","now that's a story worth telling.","very cool, very cool."]],"gutter":[["Well, {name} finds the gutter","That one's in the channel for {name}","No pins on that trip for {name}","{name} sends one down the gutter","The gutter claims {name}'s delivery"],["it happens, man.","the lane abides, I guess.","sometimes the ball takes a different road.","we'll just roll with it.","nothing to get worked up about."]],"normal":[["{name} takes {pins} pins","That's {pins} down for {name}","Well, {name} gets {pins}","A {pins}-pin delivery from {name}","{name} knocks over {pins}"],["and the game keeps moving.","steady as she goes, man.","could be worse, could be better.","just another turn of the wheel.","let's see what comes next."]],"perfect":[["{name} is still perfect through {frame}","No misses yet for {name}, through {frame}","That perfect run from {name} continues through {frame}","{name} has kept it clean through {frame}","Through {frame}, {name} hasn't missed"],["try not to jinx it, man.","that's some serious focus.","the room is getting quiet.","let's not get ahead of ourselves.","one ball at a time."]],"final_perfect":[["Three hundred for {name}","A perfect 300 from {name}","Every strike, every frame: {name} hits 300","{name} just bowled a 300","Well, {name} has done it, 300"],["that is extraordinary, man.","a night to remember.","I mean, wow. Just wow.","the whole place can appreciate that.","that really ties the night together."]],"entrance":[["Here comes {name}","{name} steps into the light","Well, {name} has arrived","A little welcome for {name}","{name} takes the approach"],["and the lanes are ready.","nice and easy, man.","let's see what happens.","no pressure, just bowling.","the evening is young."]]}

def _choose(session, key, pairs, **values):
    # 5 x 5 combinations; avoid repeating until the pool has cycled.
    history = getattr(session, '_dude_used', None) if session is not None else None
    if history is None and session is not None:
        history = {}; session._dude_used = history
    used = history.setdefault(key, set()) if history is not None else set()
    available = [n for n in range(len(pairs[0]) * len(pairs[1])) if n not in used]
    if not available:
        used.clear(); available = list(range(len(pairs[0]) * len(pairs[1])))
    rng = getattr(session, 'rng', None)
    index = (rng.choice(available) if rng and hasattr(rng, 'choice') else random.choice(available))
    used.add(index)
    a, b = divmod(index, len(pairs[1]))
    return (pairs[0][a] + ' ' + pairs[1][b]).format(**values)

def stage_line(session, stage, event):
    if stage not in STAGES: return 'The shot is underway, man.'
    return '🎙️ ' + _choose(session, 'stage:' + stage, STAGES[stage], name=event.get('bowler','Our bowler'))

def event_line(session, kind, event):
    pairs = EVENTS.get(kind, EVENTS['normal'])
    return '🎙️ ' + _choose(session, 'event:' + kind, pairs, name=event.get('bowler','Our bowler'), pins=event.get('pins',0), leave=event.get('split_name') or event.get('leave_name') or 'that split', frame=event.get('frame','?'))
